import json, urllib.request
from playwright.sync_api import sync_playwright
prov=json.load(open('/tmp/prov.json')); B='http://localhost:8765/'; erros=[]; n=0
def api(o): return json.loads(urllib.request.urlopen(urllib.request.Request(B+'exec', data=json.dumps(o).encode())).read())
def ok(m):
    global n; n+=1; print('ok ',m)
with sync_playwright() as p:
    br=p.chromium.launch(executable_path='/usr/bin/google-chrome', args=['--no-sandbox'])
    pg=br.new_page(viewport={'width':1366,'height':900})
    pg.on('console', lambda m: erros.append(m.text) if m.type=='error' and 'cdnjs' not in str(m.location) and 'ERR_FAILED' not in m.text else None)
    pg.on('pageerror', lambda e: erros.append('PAGEERR '+str(e)))
    pg.on('dialog', lambda d: d.accept())
    pg.add_init_script("localStorage.setItem('jornada_gas_url','http://localhost:8765/exec')")
    pg.goto(B); pg.fill('#login-email','marques.marcela@estacio.br'); pg.fill('#login-senha',prov['admin']); pg.click('#btn-entrar')
    pg.wait_for_selector('#form-troca:not([hidden])'); pg.fill('#troca-atual',prov['admin']); pg.fill('#troca-nova','Admin2026b'); pg.fill('#troca-conf','Admin2026b'); pg.click('#form-troca button.primario')
    pg.wait_for_function("document.body.dataset.tela==='app'")
    assert pg.locator('#menu a[data-rota="s/evasao"]').count()==1; ok('Evasão aparece no menu')
    pg.goto(B+'#/s/evasao'); pg.wait_for_timeout(2000)
    f=[x for x in pg.frames if 'modulos/evasao' in x.url][0]; f.wait_for_selector('.bloco', timeout=15000)
    txt=f.inner_text('#area'); assert 'Aluno matriculado · Ímpar' in txt and 'Comparativo dos períodos' in txt, txt; ok('painel abre no período Ímpar com o comparativo')
    f.click('#periodos button[data-p="par"]'); f.wait_for_timeout(300)
    txt=f.inner_text('#area'); assert 'Ciclo 2025.2' in txt and 'recaptura' in txt, txt; ok('Par: mostra o ciclo 2025.2 encerrado, seguindo para recaptura')
    pg.screenshot(path='/home/claude/testes/tela_evasao_painel.png')
    f.click('#abas button[data-aba="matriculados"]'); f.wait_for_selector('tr[data-id="ev_db_202402000201"]')
    assert 'registrar objeção' in f.inner_text('tr[data-id="ev_db_202402000201"]'); ok('cancelado da base Par aparece sozinho, pedindo a objeção')
    f.click('tr[data-id="ev_db_202402000201"]'); f.wait_for_selector('#form-ev')
    f.select_option('[name=obj]','Outro'); assert f.is_visible('[name=obj_outro]'); ok('"Outro" abre o campo para descrever')
    f.click('#btn-salvar'); f.wait_for_timeout(400); assert f.locator('#form-ev').count()==1; ok('sem descrever o "Outro" não salva')
    f.fill('[name=obj_outro]','Vai fazer intercâmbio'); f.fill('[name=obs]','Pretende voltar em 2027'); f.click('#btn-salvar')
    f.wait_for_selector('tr[data-id="ev_db_202402000201"]', timeout=10000)
    lin=f.inner_text('tr[data-id="ev_db_202402000201"]'); assert 'intercâmbio' in lin, lin; assert 'Marcela' in lin, lin; ok('objeção "Outro" salva no nome de quem está logado')
    f.click('#periodos button[data-p="impar"]'); f.wait_for_timeout(300)
    assert f.locator('tr[data-id="ev_db_202402000201"]').count()==0 and f.locator('tr[data-id]').count()==0; ok('Ímpar não mistura o registro do Par')
    f.click('#periodos button[data-p="par"]'); f.click('#abas button[data-aba="renovacao"]'); f.wait_for_selector('tr[data-id="P1"]')
    assert 'Mudança de cidade' in f.inner_text('tr[data-id="P1"]') and 'Ciclo encerrado' in f.inner_text('#area'); ok('Renovação: evadido com a objeção vinda do acionamento')
    f.click('tr[data-id="P1"]'); f.wait_for_selector('#modal-corpo .lembrete'); assert 'recaptura' in f.inner_text('#modal-corpo') and f.locator('#form-rev').count()==0; ok('ciclo encerrado não deixa reverter')
    pg.screenshot(path='/home/claude/testes/tela_evasao_renovacao.png')
    f.click('[data-fechar]')
    # ciclo aberto (2026.1, sem prazo vencido): marca um evadido e reverte pela tela
    tok=pg.evaluate("()=>{ for (const k of Object.keys(localStorage)) { try { const o=JSON.parse(localStorage.getItem(k)); if (o && o.token && o.me) return o.token; } catch(e){} } return ''; }")
    r=api({'acao':'renovacao.salvar_acionamento','token':tok,'acionamento':{'id':'evr2','alunoId':'R2','nomeAluno':'Renova Exemplo 2','tipo':'Ligação','obs':'[Objeção: Trabalho / falta de tempo]','stAl':'Evadido','ciclo':'2026.1'}}); assert r.get('ok'), r
    pg.goto(B+'#/inicio'); pg.wait_for_timeout(500); pg.goto(B+'#/s/evasao'); pg.wait_for_timeout(2000)
    f=[x for x in pg.frames if 'modulos/evasao' in x.url][0]; f.wait_for_selector('.bloco', timeout=15000)
    f.click('#abas button[data-aba="renovacao"]'); f.wait_for_selector('tr[data-id="R2"]')
    assert 'Ciclo aberto' in f.inner_text('#area') and 'pode reverter' in f.inner_text('tr[data-id="R2"]'); ok('Ímpar 2026.1 aberto: evadido pode ser revertido')
    f.click('tr[data-id="R2"]'); f.wait_for_selector('#form-rev'); f.select_option('[name=status]','Em negociação'); f.fill('[name=obs]','Aceitou negociar a dívida')
    f.click('#btn-rev'); f.wait_for_function("!document.querySelector('tr[data-id=\"R2\"]')", timeout=10000)
    r=api({'acao':'renovacao.carregar_alunos','token':tok,'ciclo':'2026.1'}); st=[a['status'] for a in r['alunos'] if a['id']=='R2'][0]; assert st=='Em negociação', st; ok('reversão muda o status na Renovação para Em negociação')
    br.close()
print(n,'passos ok'); print('erros:', erros or 'nenhum')
